import{bQ as t,aL as l,u as o,G as a}from"./chunks/framework.C1gZXFVa.js";const b=JSON.parse('{"title":"Releases","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/releases.md","filePath":"en/guide/releases.md"}'),s={name:"en/guide/releases.md"};function i(r,e,d,n,c,h){return l(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h1><blockquote><p><strong>Current version 2.0.0</strong> (2026-10-27): a ground-up refactor of the installer for current systems. This page is the summary; full notes are in the <a href="https://github.com/ghl1024/ansible-offline-install/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a> and the <a href="https://github.com/ghl1024/ansible-offline-install/releases/tag/v2.0.0" target="_blank" rel="noreferrer">GitHub Release</a>.</p></blockquote><h2 id="_2-0-0-highlights" tabindex="-1">2.0.0 highlights <a class="header-anchor" href="#_2-0-0-highlights" aria-label="Permalink to &quot;2.0.0 highlights&quot;">​</a></h2><ul><li>Offline installer (<code>install.sh</code>) based on a local wheelhouse and an isolated Python venv; pip runs with <code>--no-index</code>, no network at install time.</li><li>Bundle builder (<code>scripts/make-offline-bundle.sh</code>) producing a versioned <code>.tar.gz</code> plus a SHA256 checksum for Release distribution.</li><li>Support matrix: EL 9 family (Rocky / Alma / RHEL / CentOS Stream 9), Ubuntu 24.04 / 22.04, Debian 12 - 8 combinations across x86_64 and ARM64; CI and the release workflow cover the same 8 combinations and build, install-test and publish fully automatically.</li><li>Ansible pinned to <code>ansible-core==2.18.19</code>, Python &gt;= 3.11 required; both scripts auto-detect a suitable interpreter.</li><li>Galaxy collections bundled for offline install: <code>ansible.posix</code> and <code>community.general</code> (with dependencies) by default.</li><li>Scripts print Chinese by default, with <code>--lang en</code> or <code>ANSIBLE_OFFLINE_LANG=en</code> for English; READMEs are bilingual.</li><li>Published on four platforms: GitHub (primary) plus Gitee / GitCode / CNB mirrors in China, with identical release content (see <a href="/en/guide/download">Download &amp; Verify</a>).</li></ul><h2 id="release-assets" tabindex="-1">Release assets <a class="header-anchor" href="#release-assets" aria-label="Permalink to &quot;Release assets&quot;">​</a></h2><blockquote><p>Every release has <strong>16 assets</strong>:</p></blockquote><ul><li>Offline bundles for the 8 platform combinations</li><li>A matching <code>.sha256</code> checksum file for each</li></ul><h2 id="roadmap-completed" tabindex="-1">Roadmap (completed) <a class="header-anchor" href="#roadmap-completed" aria-label="Permalink to &quot;Roadmap (completed)&quot;">​</a></h2><ul><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>Galaxy collections bundled for offline install</li><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>CI: script checks + install tests for 8 OS/arch combinations</li><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>Release bundles for x86_64 and ARM64, built, install-tested and published by GitHub Actions on native ARM64 runners</li><li class="todo"><input class="todo-checkbox" type="checkbox" checked disabled>This documentation site (private source repository; only the built output is published to the primary repository&#39;s GitHub Pages)</li></ul><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><ul><li>Files in the primary repository, listed in the order you will use them:</li></ul><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>install.sh</code></td><td>The installer for the offline machine; the only file most users need</td></tr><tr><td><code>scripts/make-offline-bundle.sh</code></td><td>The bundle builder for the online machine</td></tr><tr><td><code>requirements.txt</code></td><td>ansible-core version pin</td></tr><tr><td><code>collections-requirements.yml</code></td><td>Collections bundled with the offline package</td></tr><tr><td><code>.github/workflows/ci.yml</code></td><td>CI: script checks + install tests for 8 OS/arch combos</td></tr><tr><td><code>.github/workflows/release.yml</code></td><td>Release: builds, tests and publishes bundles for all 8 targets</td></tr><tr><td><code>CHANGELOG.md</code></td><td>Version history</td></tr><tr><td><code>LICENSE</code></td><td>MIT license</td></tr></tbody></table>',12)])])}const p=t(s,[["render",i]]);export{b as __pageData,p as default};
